const content = $input.item.json.choices?.[0]?.message?.content || $input.item.json.content;
let idea;
try { idea = JSON.parse(content); } catch(e) { const m = content.match(/\{[\s\S]*\}/); idea = m ? JSON.parse(m[0]) : {}; }
// normalize slug
if (!idea.slug) idea.slug = (idea.title||'product').toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,60);
return [{ json: idea }];
